// Epidemiology Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: rates and measures, study designs, global response and MMWR-style
// outbreak and surveillance reasoning not covered in Practice Test 1.
import {q, mix} from './q.js';
const CDC='CDC, Principles of Epidemiology in Public Health Practice', WHO='World Health Organization', MMWR='CDC, Morbidity and Mortality Weekly Report';
const INTRO='Introduction to Epidemiology', WORLD='World and Government Response to Infectious Diseases', MW='CDC: Morbidity and Mortality Weekly Report';

export default {
 id:'epidemiology-2',
 event:'Epidemiology',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'CDC Principles of Epidemiology (PH 101), WHO materials and CDC’s Morbidity and Mortality Weekly Report',
 plan:[{area:INTRO,weight:30},{area:WORLD,weight:20},{area:MW,weight:50}],
 questions:mix([
  q(INTRO,'What does the epidemiologic triangle consist of?','Agent, host and environment',['Person, place and time','Cause, effect and cure','Vector, virus and vaccine'],'A','Disease results from the interaction of an agent, a susceptible host and the environment.',CDC),
  q(INTRO,'Which term describes the usual, expected level of a disease in a population?','Endemic',['Epidemic','Pandemic','Sporadic'],'B','An epidemic is an increase above the expected level in a given area.',CDC),
  q(INTRO,'A town of 50,000 has 200 people living with diabetes on January 1. What is the point prevalence per 1,000?','4 per 1,000',['0.4 per 1,000','40 per 1,000','400 per 1,000'],'C','Prevalence counts all existing cases: 200 ÷ 50,000 = 0.004, which is 4 per 1,000 population.',CDC),
  q(INTRO,'In a cohort study, the risk of disease is 0.30 in the exposed and 0.10 in the unexposed. What is the risk ratio?','3.0',['0.3','0.2','2.0'],'D','Risk ratio = risk in exposed ÷ risk in unexposed = 0.30 ÷ 0.10 = 3.0.',CDC),
  q(INTRO,'Which measure is used to estimate risk in a case-control study?','Odds ratio',['Risk ratio','Attack rate','Incidence rate'],'A','Case-control studies start with disease status, so true risk cannot be calculated directly.',CDC),
  q(INTRO,'Which study design measures exposure and disease at a single point in time?','Cross-sectional study',['Cohort study','Case-control study','Clinical trial'],'B','Cross-sectional surveys give a snapshot of prevalence but cannot show which came first.',CDC),
  q(INTRO,'Which term describes the time from infection to the onset of symptoms?','Incubation period',['Latent period','Infectious period','Generation time'],'C','The incubation period helps investigators find the likely time of exposure.',CDC),
  q(INTRO,'Which type of bias occurs when cases remember past exposures better than controls?','Recall bias',['Selection bias','Observer bias','Lead-time bias'],'D','People who are sick often search their memory harder for possible causes.',CDC),
  q(INTRO,'A person who carries an infectious agent without symptoms and can spread it is called a:','Carrier',['Vector','Reservoir','Fomite'],'A','Typhoid Mary was a famous asymptomatic carrier of Salmonella Typhi.',CDC),
  q(INTRO,'Which is an example of a fomite?','A contaminated doorknob',['A mosquito biting skin','An infected person','Polluted river water'],'B','Fomites are inanimate objects that carry infectious agents from person to person.',CDC),
  q(INTRO,'Which level of prevention is screening for early cancer?','Secondary prevention',['Primary prevention','Tertiary prevention','Primordial only'],'C','Primary prevents disease; secondary finds it early; tertiary limits disability.',CDC),
  q(INTRO,'Of 1,000 people tested, 90 of 100 with a disease test positive. What is the sensitivity?','90%',['10%','9%','100%'],'D','Sensitivity = true positives ÷ all people with disease = 90 ÷ 100.',CDC),
  q(INTRO,'Which population is used as the denominator in a crude death rate?','The total population at midyear',['Only the people who died','Only adults over age 65','Only people with the disease'],'A','Crude death rate = deaths in a year ÷ midyear population, often per 100,000.',CDC),
  q(INTRO,'Which mode of transmission involves a mosquito carrying a pathogen between people?','Vector-borne',['Airborne','Direct contact','Common vehicle'],'B','Malaria, dengue and West Nile virus are spread by mosquito vectors.',CDC),
  q(INTRO,'Herd immunity protects which group most directly?','People who cannot be vaccinated',['Only people who are vaccinated','Only health care workers','Only animals in the area'],'C','When enough people are immune, transmission chains break, protecting the vulnerable.',CDC),
  q(WORLD,'Which global health agency is part of the United Nations?','World Health Organization',['Centers for Disease Control','National Institutes of Health','Food and Drug Administration'],'D','The WHO coordinates international health responses and sets global standards.',WHO),
  q(WORLD,'Which disease is the target of a global eradication campaign using vaccines and is now limited to a few countries?','Polio',['Influenza','Tuberculosis','Malaria'],'A','Wild poliovirus remains endemic only in Pakistan and Afghanistan; vaccine-derived cases occur elsewhere.',WHO),
  q(WORLD,'Which disease was eradicated in animals worldwide in 2011?','Rinderpest',['Rabies','Anthrax','Avian flu'],'B','Rinderpest, a cattle disease, is the second disease ever eradicated, after smallpox.',WHO),
  q(WORLD,'Which U.S. agency regulates vaccines and approves them for use?','FDA',['CDC','OSHA','EPA'],'C','The CDC’s ACIP then recommends how approved vaccines should be used.',CDC),
  q(WORLD,'Which system lets the public and providers report possible vaccine side effects?','VAERS',['NNDSS','CODIS','FoodNet'],'D','VAERS is an early warning system; reports alone do not prove the vaccine caused an event.',CDC),
  q(WORLD,'What is a notifiable disease?','One that must be reported',['One that is never contagious','One caused only by genes','One found only in animals'],'A','States decide which diseases are reportable, and CDC compiles data nationally.',CDC),
  q(WORLD,'Which disease has a vaccine that led to elimination of endemic spread in the U.S. in 2000?','Measles',['Influenza','HIV','Tuberculosis'],'B','Outbreaks still occur when travelers bring measles into undervaccinated communities.',CDC),
  q(WORLD,'Which program tracks foodborne illness in sentinel sites across the United States?','FoodNet',['VAERS','BRFSS','NHANES'],'C','FoodNet monitors infections such as Salmonella, Campylobacter and E. coli O157.',CDC),
  q(WORLD,'What is the main purpose of travel health notices from the CDC?','Warn travelers of risks abroad',['Sell plane tickets to travelers','Report weather at airports','List hotel prices by country'],'D','Notices range from practicing usual precautions to avoiding nonessential travel.',CDC),
  q(WORLD,'Which international group helps fund vaccines for children in low-income countries?','Gavi',['UNESCO','The IMF','The WTO'],'A','Gavi works with WHO, UNICEF and donors to expand vaccine access.',WHO),
  q(MW,'What is the first step in the CDC’s steps of an outbreak investigation?','Prepare for field work',['Implement control measures','Write the final report','Test hypotheses'],'B','Preparation includes research, supplies and coordination with partners.',MMWR),
  q(MW,'Which step confirms that an apparent outbreak is real and not a reporting artifact?','Verify the outbreak exists',['Communicate findings','Develop hypotheses','Conduct a cohort study first'],'C','Investigators compare current counts with expected levels and check for changes in reporting.',MMWR),
  q(MW,'In a case definition, which level requires laboratory confirmation?','Confirmed case',['Probable case','Possible case','Suspected case'],'D','Probable cases meet clinical criteria and have an epidemiologic link but no lab test.',MMWR),
  q(MW,'Which graph shows the number of cases by date of illness onset?','Epidemic curve',['Pie chart','Scatter plot','Box plot'],'A','The shape of the epi curve suggests how the disease spread and when exposure likely happened.',MMWR),
  q(MW,'An epi curve shows cases spread over a long period without a clear peak. What does this suggest?','Continuous common source',['Single point source','Person-to-person spread','No outbreak at all'],'B','Ongoing exposure, such as a contaminated water supply, causes a plateau.',MMWR),
  q(MW,'At a wedding, 60 of 80 people who ate the fish became ill, versus 10 of 70 who did not. What is the attack rate among those who ate fish?','75%',['14%','60%','86%'],'C','60 ÷ 80 = 0.75, or 75%; the rate among non-eaters is about 14%.',MMWR),
  q(MW,'Using the same wedding data (60 of 80 ill vs. 10 of 70), what is the risk ratio for eating fish?','About 5.3',['About 0.2','About 1.5','About 10'],'D','Risk ratio = 0.75 ÷ 0.143 ≈ 5.3, strongly pointing to the fish.',MMWR),
  q(MW,'Which measure in an MMWR table compares disease rates between two groups by subtraction?','Rate difference',['Odds ratio','Rate ratio','Case-fatality rate'],'A','The rate difference shows the excess rate attributable to an exposure.',MMWR),
  q(MW,'What does the abbreviation “95% CI” in an MMWR report describe?','The range likely to contain the true value',['The percent of cases confirmed by labs','The number of people interviewed','The ratio of cases to controls'],'B','A confidence interval that includes 1.0 for a ratio is not statistically significant.',MMWR),
  q(MW,'Which surveillance type uses selected sites to collect detailed data?','Sentinel surveillance',['Passive surveillance','Mandatory surveillance','Universal surveillance'],'C','Sentinel sites, such as certain clinics, track trends like influenza activity.',MMWR),
  q(MW,'Which pathogen is the leading cause of hospitalization from foodborne illness in the U.S.?','Nontyphoidal Salmonella',['Norovirus only','Listeria','Clostridium botulinum'],'D','Norovirus causes the most illnesses, but Salmonella causes the most hospitalizations.',MMWR),
  q(MW,'Which foodborne pathogen is especially dangerous for pregnant women and is linked to deli meats and soft cheeses?','Listeria monocytogenes',['Staphylococcus aureus','Norovirus','Bacillus cereus'],'A','Listeria can cause miscarriage, stillbirth and newborn infection.',MMWR),
  q(MW,'Several people develop vomiting within 2–6 hours after eating cream-filled pastries. Which toxin is most likely?','Staph aureus toxin',['Hepatitis A virus in food','Botulinum toxin','Salmonella Typhi'],'B','Preformed staph toxin causes rapid vomiting and is not destroyed by reheating.',MMWR),
  q(MW,'Which tool links genetically similar bacterial isolates across states to detect multistate outbreaks?','PulseNet',['VAERS','BRFSS','NHANES survey'],'C','PulseNet now uses whole genome sequencing to compare isolates.',MMWR),
  q(MW,'What does the term “excess deaths” describe in surveillance reports?','Deaths above the expected',['Deaths from any accident','All deaths in a given year','Deaths in only one hospital'],'D','Excess death estimates helped measure the full impact of COVID-19.',MMWR),
  q(MW,'Which national survey measures health behaviors such as smoking through telephone interviews?','BRFSS',['NHANES','VAERS','PulseNet'],'A','The Behavioral Risk Factor Surveillance System surveys adults in every state.',MMWR),
  q(MW,'A cluster of rare Pneumocystis pneumonia cases reported in MMWR in 1981 was the first report of which disease?','AIDS',['SARS','Ebola','Lyme disease'],'B','The June 5, 1981, MMWR report is considered the first published report of AIDS.',MMWR),
  q(MW,'In an outbreak, what is the purpose of an analytic study after hypotheses are formed?','To test which exposure is linked',['To count all of the cases in the area','To report results to the media','To treat sick patients directly'],'C','Cohort or case-control studies compare exposures between ill and well people.',MMWR),
  q(MW,'In a case-control study, 40 of 50 cases and 20 of 50 controls ate sprouts. What is the odds ratio?','6.0',['1.5','2.0','4.0'],'D','Odds ratio = ad ÷ bc = (40 × 30) ÷ (10 × 20) = 1,200 ÷ 200 = 6.0, pointing to the sprouts.',MMWR),
  q(MW,'Why do investigators use a dot map of cases near a water pump, like John Snow did?','To find a common geographic source',['To count the total population','To measure the time of onset','To compare vaccine rates'],'A','Snow’s 1854 map linked cholera cases to the Broad Street pump in London.',MMWR),
  q(MW,'Which pathogen causes most outbreaks of vomiting and diarrhea on cruise ships?','Norovirus',['Legionella','Listeria','Salmonella'],'B','Norovirus spreads easily through food, surfaces and close contact.',MMWR),
  q(MW,'Which feature of tuberculosis makes contact investigations important?','It spreads through the air',['It spreads only through food','It never causes symptoms','It is cured without treatment'],'C','Close contacts are tested and treated for latent TB to prevent active disease.',MMWR),
  q(MW,'Why might a sudden rise in reported cases not be a real outbreak?','A new test or reporting change',['A smaller population size','Cases always decline in winter','Fewer people seek medical care'],'D','Changes in testing, reporting or case definitions can create artificial increases.',MMWR),
  q(MW,'Which group decides U.S. immunization schedules that are published in MMWR?','ACIP',['FDA','WHO','OSHA'],'A','The Advisory Committee on Immunization Practices advises the CDC director.',MMWR),
  q(MW,'Which pathogen often causes outbreaks linked to cooling towers and hot tubs?','Legionella',['Giardia','Norovirus','Hepatitis A'],'B','Legionella grows in warm water and spreads through inhaled mist.',MMWR)
 ],3220)
};
